/* Triggering Hardware Acceleration (GPU layer creation) */
.animated-box {
  /* Using transform instead of left/top avoids Layout and Paint entirely! */
  transform: translate3d(100px, 0, 0);

  /* Opacity is also strictly a Compositor-only operation */
  opacity: 0.5;

  /* WILL-CHANGE hints the browser to create a GPU layer early */
  will-change: transform, opacity;
}
